function LoanEligibilityCalculator(){
  const [income,setIncome]=useState(60000),[existingEmi,setExistingEmi]=useState(0),[ratio,setRatio]=useState(40),[rate,setRate]=useState(10),[years,setYears]=useState(20);
  const maxEmi=Math.max(0,income*ratio/100-existingEmi),months=years*12,monthlyRate=rate/1200;
  const eligibleLoan=monthlyRate===0?maxEmi*months:maxEmi*(1-Math.pow(1+monthlyRate,-months))/monthlyRate;
  return <><PageIntro title="Loan eligibility calculator" kicker="TOOLS FOR YOUR PLANS" copy="Estimate a possible loan amount from income, existing EMIs, an assumed repayment share and a chosen term."/><main className="container content-area"><div className="banking-tool-layout"><section className="banking-tool-form"><div className="eyebrow"><span className="eyebrow-dot"/> YOUR ESTIMATE</div><h2>Explore a repayment range.</h2><p>Enter monthly figures in Indian rupees. Adjust the repayment share to test your own planning assumption.</p><label htmlFor="monthly-income">Monthly take-home income (₹)</label><input id="monthly-income" type="number" min="0" step="1000" value={income} onChange={e=>setIncome(Math.max(0,Number(e.target.value)))}/><label htmlFor="existing-emi">Existing monthly loan payments (₹)</label><input id="existing-emi" type="number" min="0" step="500" value={existingEmi} onChange={e=>setExistingEmi(Math.max(0,Number(e.target.value)))}/><label htmlFor="repayment-share">Share of income for all EMIs <b>{ratio}%</b></label><input id="repayment-share" type="range" min="10" max="70" step="1" value={ratio} onChange={e=>setRatio(Number(e.target.value))}/><label htmlFor="eligibility-rate">Annual interest rate (%)</label><input id="eligibility-rate" type="number" min="0" max="40" step="0.1" value={rate} onChange={e=>setRate(Math.max(0,Number(e.target.value)))}/><label htmlFor="eligibility-years">Repayment term (years)</label><input id="eligibility-years" type="number" min="1" max="40" value={years} onChange={e=>setYears(Math.max(1,Math.min(40,Number(e.target.value))))}/></section><aside className="banking-tool-result"><span className="eyebrow">INDICATIVE ESTIMATE</span><p>Estimated maximum loan amount</p><strong>₹{Math.round(eligibleLoan).toLocaleString('en-IN')}</strong><div className="tool-result-details"><span>Estimated EMI capacity<b>₹{Math.round(maxEmi).toLocaleString('en-IN')} / month</b></span><span>Income used in assumption<b>{ratio}%</b></span><span>Term used<b>{years} years</b></span></div><p className="tool-disclaimer">Illustration only. The repayment share and rate are user-selected assumptions, not RBI-prescribed eligibility limits or a bank offer. Actual eligibility and pricing depend on the lender’s policy, verified income, existing obligations, credit assessment, product conditions and applicable disclosures.</p><Link to="/contact" className="button button-gold">Ask about loan options <ArrowRight size={15}/></Link></aside></div></main></>}

function InterestRateCalculator(){
  const [principal,setPrincipal]=useState(100000),[maturity,setMaturity]=useState(108000),[years,setYears]=useState(1),[frequency,setFrequency]=useState(4);
  const hasGain=principal>0&&maturity>=principal&&years>0;
  const annualRate=hasGain?(Math.pow(maturity/principal,1/(frequency*years))-1)*frequency*100:0;
  const interest=hasGain?maturity-principal:0;
  return <><PageIntro title="Interest rate calculator" kicker="TOOLS FOR YOUR PLANS" copy="Estimate an implied annualised rate from a principal, target maturity value, term and compounding frequency. Prefilled figures are examples, not a Progressive rate quote."/><main className="container content-area"><div className="banking-tool-layout"><section className="banking-tool-form"><div className="eyebrow"><span className="eyebrow-dot"/> RATE ESTIMATE</div><h2>Calculate an implied return.</h2><p>Enter the investment and maturity values from a product illustration or offer document.</p><label htmlFor="rate-principal">Principal amount (₹)</label><input id="rate-principal" type="number" min="1" step="1000" value={principal} onChange={e=>setPrincipal(Math.max(1,Number(e.target.value)))}/><label htmlFor="rate-maturity">Target maturity value (₹)</label><input id="rate-maturity" type="number" min="1" step="1000" value={maturity} onChange={e=>setMaturity(Math.max(1,Number(e.target.value)))}/><label htmlFor="rate-term">Term (years)</label><input id="rate-term" type="number" min="0.25" max="50" step="0.25" value={years} onChange={e=>setYears(Math.max(.25,Number(e.target.value)))}/><label htmlFor="rate-frequency">Compounding frequency</label><select id="rate-frequency" value={frequency} onChange={e=>setFrequency(Number(e.target.value))}><option value="1">Yearly</option><option value="2">Half-yearly</option><option value="4">Quarterly</option><option value="12">Monthly</option></select></section><aside className="banking-tool-result"><span className="eyebrow">INDICATIVE CALCULATION</span><p>Implied nominal annual rate</p><strong>{hasGain?annualRate.toFixed(2):'0.00'}% p.a.</strong><div className="tool-result-details"><span>Principal<b>₹{principal.toLocaleString('en-IN')}</b></span><span>Target maturity<b>₹{maturity.toLocaleString('en-IN')}</b></span><span>Illustrative interest<b>₹{interest.toLocaleString('en-IN')}</b></span></div>{!hasGain&&<p className="tool-validation" role="alert">The maturity value must be at least the principal amount.</p>}<p className="tool-disclaimer">This reverse calculation assumes a fixed nominal rate compounded at the selected frequency. Actual deposit returns may differ because of payout method, tax, premature closure, day-count conventions, product rules and bank rates. Check the bank’s current disclosure before deciding.</p><Link to="/interest-rates" className="button button-gold">View interest rate information <ArrowRight size={15}/></Link></aside></div></main></>}

function ServiceChargeFinder(){
  const [query,setQuery]=useState(''),[category,setCategory]=useState('All services');
  const rows=[['Account maintenance and minimum balance','Accounts','Account maintenance, minimum balance requirements and related fees.'],['ATM and debit card services','Cards and ATM','Card issuance, replacement, ATM use and related service fees.'],['Fund transfers and payments','Payments','NEFT, RTGS and other electronic payment service charges.'],['Cheque and demand draft services','Cheques','Cheque books, returned cheques, collection and demand drafts.'],['Loan processing and repayment','Loans','Processing, documentation, prepayment and repayment related fees.'],['Deposit services','Deposits','Premature closure, duplicate advice and deposit servicing fees.'],['Account statements and certificates','Documents','Statements, balance certificates and other requested documents.']];
  const categories=['All services',...new Set(rows.map(row=>row[1]))];
  const shown=rows.filter(([name,group,copy])=>(category==='All services'||group===category)&&(`${name} ${group} ${copy}`).toLowerCase().includes(query.toLowerCase()));
  return <><PageIntro title="Service category finder" kicker="TOOLS AND TRANSPARENCY" copy="Browse common service categories. This tool does not quote fees; the current service-charge schedule could not be verified from the linked bank document. Contact the bank to confirm amounts, conditions and effective date."/><main className="container content-area"><div className="charge-finder"><div className="charge-finder-controls"><label className="charge-search-field"><Search size={17}/><input aria-label="Search service categories" placeholder="Search a category, e.g. ATM or statement" value={query} onChange={e=>setQuery(e.target.value)}/></label><label className="charge-category-field">Category<select value={category} onChange={e=>setCategory(e.target.value)}>{categories.map(item=><option key={item}>{item}</option>)}</select></label></div><div className="charge-results-summary">{shown.length} service {shown.length===1?'category':'categories'} found <span>Category search only · no fee amounts shown</span></div><div className="charge-result-list">{shown.map(([name,group,copy])=><article key={name}><span className="charge-result-icon"><FileText size={18}/></span><div><span className="charge-result-group">{group}</span><h2>{name}</h2><p>{copy}</p><small>Ask the bank for its current amount, effective date, taxes and any applicable exemption.</small></div><Link to="/contact">Ask the bank <ArrowUpRight size={14}/></Link></article>)}</div>{shown.length===0&&<div className="charge-empty"><Search size={20}/><b>No matching service found</b><span>Try another search term or choose a different category.</span></div>}<div className="banking-guidance"><ShieldCheck size={18}/><p>Confirm applicable charges and conditions directly with the bank before making a transaction. <a href="https://www.rbi.org.in/Scripts/NotificationUser.aspx?Id=9862" target="_blank" rel="noreferrer">RBI guidance on transparent rate and charge disclosures <ArrowUpRight size={12}/></a></p></div></div></main></>}

function SupportHub(){const items=[['FAQs','Find answers to common banking questions.','/faqs',CircleHelp],['Grievance redressal','Learn how to raise a customer concern.','/grievance-redressal',HeartHandshake],['Report fraud','Security and fraud reporting information.','/report-fraud',ShieldCheck],['Customer awareness','Guidance on keeping banking details private.','/customer-awareness',LockKeyhole],['Downloads and forms','Browse forms and documents.','/downloads',Download]];return <><PageIntro title="Customer support" kicker="HERE WHEN YOU NEED US" copy="Find published contact details, complaint guidance, and documents."/><main className="container content-area"><div className="support-intro"><div className="support-intro-icon"><HeartHandshake size={23}/></div><div><b>Customer Support</b><p>Use the bank’s published contact channels.</p></div><Link to="/contact" className="text-link">Contact us <ArrowRight size={14}/></Link></div><div className="support-directory">{items.map(([title,desc,path,Icon],i)=><Link to={path} key={path}><span className="support-directory-num">0{i+1}</span><Icon size={18}/><span><b>{title}</b><small>{desc}</small></span><ArrowUpRight size={15}/></Link>)}</div><CTA title="Need help finding the right information?" copy="Browse support topics or contact the bank."/></main></>}

function Faqs(){const [open,setOpen]=useState(0);const questions=[['What does this website do?','It is a static information frontend. It helps you explore product categories, read published documents, use illustrative calculators and find Head Office details. It does not log you in, access accounts, accept applications or send enquiries.'],['Is a displayed rate or fee guaranteed to be current?','No. The bank documents available in the reviewed sources have effective dates in 2024 or 2025. Open the latest official schedule or contact the bank and confirm its effective date before relying on a rate or charge.'],['What account types are listed?','The bank\'s FY 2024-25 report shows savings and current deposits. Ask the bank about eligibility, minimum balance, documents, transaction limits and account terms.'],['What deposit options can I explore?','The official material confirms term deposits; the bank\'s service-charge PDF also references recurring deposit passbooks. Confirm whether recurring deposits are currently offered and ask about tenor, payout, premature closure and nomination terms.'],['How do I estimate a loan EMI or FD value?','Use the calculators under Tools. They are illustrative mathematical estimates, not a quote, sanction, eligibility decision or bank offer.'],['Where is the Head Office?','505, The Metropole, J.P. Road, Ghatkopar (West), Mumbai 400086. Telephone numbers and email are listed on the Contact page; confirm details before sending sensitive information.'],['How do I raise a complaint?','First contact the bank and keep the complaint reference and dates. If its response is unsatisfactory, or there is no response within 30 days, you may be eligible to approach RBI under RB-IOS 2026. Check scheme coverage and eligibility. This site does not receive complaints.'],['How do I report suspected fraud?','Contact your bank promptly using a verified official channel. Do not share PINs, passwords or OTPs. For unauthorised electronic transactions, follow the current official RBI and bank reporting instructions. This page is not a reporting channel.'],['Does this site store my details?','No. This static frontend has no account system or backend enquiry submission. Avoid entering personal or account details.']];return <><PageIntro title="Frequently asked questions" kicker="CUSTOMER SUPPORT" copy="Practical answers about products, documents, tools, safety and what this static information site can and cannot do." crumb={[["Customer support","/customer-support"],["FAQs"]]}/><main className="container content-area"><div className="faq-list">{questions.map(([q,a],i)=><div className="faq-item" key={q}><button aria-expanded={open===i} onClick={()=>setOpen(open===i?-1:i)}><span>{q}</span><span>{open===i?'−':'+'}</span></button>{open===i&&<p>{a}</p>}</div>)}</div><div className="banking-guidance"><CircleHelp size={15}/><p>For account-specific requests, contact Progressive Co-operative Bank through a verified published channel. Never use this informational website to send banking credentials.</p></div><Link className="text-link" to="/customer-support">Back to customer support <ArrowLeft size={14}/></Link></main></>}
function SupportInfo({title}){return <><PageIntro title={title} kicker="CUSTOMER SUPPORT" copy="A clear route for raising and following up on a banking complaint." crumb={[["Customer support","/customer-support"],[title]]}/><main className="container content-area"><div className="support-detail"><span className="support-detail-icon"><HeartHandshake size={22}/></span><div className="eyebrow"><span className="eyebrow-dot"/> COMPLAINT STEPS</div><h2>Raise a concern and keep a record.</h2><ol className="complaint-steps"><li><b>Contact the bank first.</b> Use a current, verified bank channel and describe the issue clearly. Ask for a complaint reference.</li><li><b>Keep your records.</b> Save the complaint reference, date, response, and relevant statements or messages. Do not include PINs, passwords or OTPs.</li><li><b>Follow up or escalate.</b> If the response is unsatisfactory, or you receive no response within 30 days, you may be able to approach RBI under the Reserve Bank–Integrated Ombudsman Scheme, 2026, subject to the Scheme’s eligibility and maintainability rules. Confirm that the bank and complaint are covered before filing.</li></ol><div className="complaint-links"><a href="https://cms.rbi.org.in" target="_blank" rel="noreferrer">RBI Complaint Management System <ArrowUpRight size={14}/></a><a href="https://old.rbi.org.in/commonman/english/scripts/faqs.aspx?id=3407" target="_blank" rel="noreferrer">RBI RB-IOS 2026 FAQs and eligibility <ArrowUpRight size={14}/></a></div><p className="complaint-note">This website does not accept or track complaints. Check the latest RBI guidance and the bank’s current grievance policy. An Ombudsman complaint may be rejected if scheme requirements are not met.</p><Link to="/contact" className="button button-gold">View bank contact information <ArrowRight size={14}/></Link></div></main></>}

function ReportFraud(){return <><PageIntro title="Report fraud" kicker="CUSTOMER SUPPORT · SECURITY" copy="Security and reporting information for customers." crumb={[["Customer support","/customer-support"],["Report fraud"]]}/><main className="container content-area"><div className="fraud-notice"><div><ShieldCheck size={22}/></div><span className="eyebrow">KEEP YOUR BANKING DETAILS PRIVATE</span><h2>Never share your PIN, password or one-time passcode.</h2><p>Do not enter credentials or account details on this website. Use the bank’s official fraud reporting channels.</p><Link to="/contact" className="button button-gold">Customer support enquiry <ArrowRight size={14}/></Link></div><div className="demo-note wide"><LockKeyhole size={15}/><span>This page does not monitor or receive fraud reports. Use verified bank channels for real support.</span></div></main></>}

function CustomerAwareness(){return <><PageIntro title="Customer awareness" kicker="SAFE BANKING INFORMATION" copy="General reminders for protecting sensitive banking details." crumb={[["Customer support","/customer-support"],["Customer awareness"]]}/><main className="container content-area"><div className="awareness-lead"><ShieldCheck size={24}/><div><b>Protect your banking information</b><p>This website does not request credentials or connect to bank accounts.</p></div></div><div className="awareness-list">{[['Keep credentials private','Never share your PIN, password or one-time passcode.'],['Check before you respond','Treat unexpected requests for credentials or payment information with care.'],['Use verified support','Use the bank’s published customer support channels.']].map(([title,copy],i)=><div key={title}><span>0{i+1}</span><b>{title}</b><p>{copy}</p></div>)}</div><Link to="/report-fraud" className="text-link">Report fraud information <ArrowRight size={14}/></Link></main></>}

function InstitutionDetail(){const {topic}=useParams();const report=docItems[0][3];const pages={'history':['History','Progressive Co-operative Bank Ltd. was incorporated on 15 October 1983 under the Maharashtra Co-operative Societies Act, 1960. Its 2024-25 annual report describes a Greater Mumbai area of operation.'], 'vision-mission':['Vision and mission','A current official vision or mission statement was not available in the source material reviewed. This page avoids attributing an unsourced slogan to the bank. For the bank’s stated priorities, refer to the Chairman’s and Directors’ report in the latest annual report.'],management:['Management and board','Board membership and senior leadership can change. Refer to the latest annual report and official notices for the current board, office holders and governance details.'], 'financial-highlights':['Financial highlights','The bank’s 2024-25 annual report contains audited statements for the year ended 31 March 2025, including the balance sheet, profit and loss account, cash-flow information and schedules. Figures in that document are historical and should be read with the auditor’s report.'], 'annual-reports':['Annual reports','The official annual report available in the reviewed source is the 42nd report for financial year 2024-25. It includes directors’ report, audited financial statements, registration and product information, product disclosures and dated rate tables.'],disclosures:['Regulatory disclosures','The annual report records the bank’s registration under the Maharashtra Co-operative Societies Act, 1960, and RBI licence details. It also contains audit and financial disclosures. Refer to the actual report and current regulatory notices; this summary is not a substitute for them.']};const page=pages[topic];if(!page)return <NotFound/>;const [title,copy]=page;return <><PageIntro title={title} kicker="ABOUT PROGRESSIVE" copy={copy} crumb={[["About us","/about"],[title]]}/><main className="container content-area"><div className="institution-detail"><Landmark size={23}/><div className="eyebrow"><span className="eyebrow-dot"/> BANK SOURCE - FY 2024-25</div><h2>{title}</h2><p>{copy}</p><a className="button button-gold" href={report} target="_blank" rel="noreferrer">Read the official annual report <ArrowRight size={14}/></a><p className="table-note"><CircleHelp size={14}/> This information reflects the report period, not necessarily the bank’s current status.</p></div></main></>}
function DisclaimerGate(){const [accepted,setAccepted]=useState(()=>{try{return sessionStorage.getItem('pucbl-disclaimer-accepted')==='yes'}catch{return false}}),[checked,setChecked]=useState(false),dialogRef=useRef(null),focusReturnRef=useRef(null);useEffect(()=>{const previousOverflow=document.body.style.overflow;if(accepted){document.body.style.overflow=previousOverflow;focusReturnRef.current?.focus?.();return}focusReturnRef.current=document.activeElement instanceof HTMLElement?document.activeElement:null;document.body.style.overflow='hidden';const dialog=dialogRef.current;dialog?.querySelector('input[type="checkbox"]')?.focus();const trapFocus=event=>{if(event.key!=='Tab'||!dialog)return;const items=[...dialog.querySelectorAll('input:not(:disabled),button:not(:disabled),a[href]')];if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}};document.addEventListener('keydown',trapFocus);return()=>{document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',trapFocus)}},[accepted]);if(accepted)return null;const continueToSite=()=>{if(!checked)return;try{sessionStorage.setItem('pucbl-disclaimer-accepted','yes')}catch{}setAccepted(true)};return <div className="disclaimer-gate"><section ref={dialogRef} className="disclaimer-dialog" role="dialog" aria-modal="true" aria-labelledby="disclaimer-gate-title" aria-describedby="disclaimer-gate-copy"><div className="disclaimer-icon"><ShieldCheck size={24}/></div><span className="home-kicker">BEFORE YOU CONTINUE</span><h1 id="disclaimer-gate-title">Website disclaimer</h1><div id="disclaimer-gate-copy" className="disclaimer-copy"><p>This website provides general information about Progressive Co-operative Bank’s products and services. It is a static information site, not an official banking channel, financial advice, an offer, or confirmation of current rates, charges, eligibility or availability.</p><p>Product terms and information may change. Check the bank’s latest official documents or contact the bank before making a financial decision. This website does not provide account access or accept applications.</p><p>Do not enter or share account numbers, passwords, PINs, one-time passcodes or full card details on this website.</p></div><label className="disclaimer-check"><input type="checkbox" checked={checked} onChange={event=>setChecked(event.target.checked)}/><span>I have read and understood this disclaimer.</span></label><button type="button" className="button button-dark disclaimer-continue" disabled={!checked} onClick={continueToSite}>Continue to website <ArrowRight size={16}/></button><small className="disclaimer-session-note">This notice appears again in a new browser session.</small></section></div>}
function Contact(){const {language}=useContext(LanguageContext);return language==='hi'?<ContactHindi/>:<ContactEnglish/>}
function ContactHindi(){return <><PageIntro title="प्रोग्रेसिव को-ऑपरेटिव बैंक से संपर्क करें" kicker="प्रधान कार्यालय · घाटकोपर पश्चिम" copy="प्रधान कार्यालय की जानकारी बैंक की वित्त वर्ष 2024–25 की वार्षिक रिपोर्ट से ली गई है। खाते से जुड़ी जानकारी के लिए बैंक के सत्यापित माध्यम का उपयोग करें। अपना PIN, पासवर्ड या OTP कभी साझा न करें।"/><main className="container content-area"><div className="contact-layout"><div className="contact-side"><div className="eyebrow"><span className="eyebrow-dot"/> प्रकाशित प्रधान कार्यालय विवरण</div><h2>बैंक से<br/><em>बात करें।</em></h2><p>कार्यालय समय की पुष्टि करके कॉल करें या प्रधान कार्यालय को लिखें। बैंक से अपनी पूछताछ सही विभाग तक पहुँचाने के लिए कहें।</p><div className="support-options"><div><IconFor icon={Building2} size={18}/><span><b>प्रधान कार्यालय</b><small>505, द मेट्रोपोल, जे.पी. रोड,<br/>घाटकोपर (पश्चिम), मुंबई · 400 086</small></span></div><div><IconFor icon={MessageCircle} size={18}/><span><b>टेलीफोन</b><small><a href="tel:+912249780131">022-49780131</a> · <a href="tel:+912249780132">022-49780132</a></small></span></div><div><IconFor icon={FileText} size={18}/><span><b>ईमेल</b><small><a href="mailto:headoffice@progressivebank.in">headoffice@progressivebank.in</a></small></span></div></div><a className="text-link" href="https://maps.google.com/?q=505+The+Metropole+JP+Road+Ghatkopar+West+Mumbai+400086" target="_blank" rel="noreferrer">प्रधान कार्यालय का नक्शा देखें <ArrowUpRight size={14}/></a></div><div className="contact-side contact-reference"><span className="eyebrow"><span className="eyebrow-dot"/> संपर्क करने से पहले</span><h2>अपना सवाल<br/><em>सही जगह पहुँचाएँ।</em></h2><ul><li>खाते या जमा से जुड़े सवाल के लिए बैंक से संपर्क करें और ग्राहक संदर्भ संख्या तैयार रखें।</li><li>सेवा संबंधी शिकायत में तारीख, माध्यम और समस्या बताएँ तथा शिकायत संदर्भ संख्या माँगें।</li><li>प्रधान कार्यालय जाने से पहले फोन करके कामकाज का समय और संबंधित विभाग पूछ लें।</li><li>धोखाधड़ी की आशंका हो तो सत्यापित माध्यम से तुरंत बैंक से संपर्क करें।</li></ul><div className="banking-guidance"><LockKeyhole size={17}/><p>यह स्थिर जानकारी वाली वेबसाइट फ़ॉर्म नहीं भेजती और व्यक्तिगत जानकारी सहेजती नहीं है। यहाँ खाता संख्या या गोपनीय जानकारी न भेजें।</p></div></div></div><p className="table-note"><CircleHelp size={14}/> संपर्क विवरण बैंक की वित्त वर्ष 2024–25 वार्षिक रिपोर्ट से लिए गए हैं। स्रोत की समीक्षा 9 अक्टूबर 2026 को की गई; विवरणों की लाइव पुष्टि नहीं हुई है। जानकारी साझा करने से पहले बैंक से पुष्टि करें।</p></main></>}
function Home(){
  const {language}=useContext(LanguageContext),hi=language==='hi';
  const links=hi?[
    ['बचत खाते','अपनी योजनाओं के लिए रोज़मर्रा की बैंकिंग।','/accounts/savings',PiggyBank],['चालू खाते','दैनिक बैंकिंग की जानकारी।','/accounts/current',CreditCard],['सावधि जमा','बचत के विकल्प देखें।','/deposits/term-deposit',Banknote],['आवर्ती जमा','नियमित बचत की आदत बनाएँ।','/deposits/recurring',PiggyBank],['गृह ऋण','घर की योजनाओं के लिए जानकारी।','/loans/housing',Building2],['शिक्षा ऋण','शिक्षा वित्त विकल्प देखें।','/loans/education',GraduationCap],['डिजिटल सेवाएँ','स्थानांतरण, अलर्ट और खाता सेवाएँ देखें।','/services',Globe2],['NEFT और RTGS','इलेक्ट्रॉनिक धन हस्तांतरण सेवाएँ।','/services/neft-rtgs',Zap],['ईएमआई कैलकुलेटर','मासिक भुगतान का अनुमान लगाएँ।','/emi-calculator',Calculator],['जमा कैलकुलेटर','जमा की अनुमानित राशि देखें।','/fd-calculator',Calculator],['ग्राहक सहायता','जानकारी खोजने में सहायता पाएँ।','/customer-support',HeartHandshake]
  ]:[['Savings accounts','Everyday banking for your plans.','/accounts/savings',PiggyBank],['Current accounts','Banking information for day-to-day needs.','/accounts/current',CreditCard],['Fixed deposits','Explore ways to save over time.','/deposits/term-deposit',Banknote],['Recurring deposits','Build a regular savings habit.','/deposits/recurring',PiggyBank],['Housing loans','Information for your home plans.','/loans/housing',Building2],['Education loans','Explore education financing information.','/loans/education',GraduationCap],['Digital services','Find transfers, alerts and account services.','/services',Globe2],['NEFT & RTGS','Learn about electronic fund transfers.','/services/neft-rtgs',Zap],['EMI calculator','Estimate a monthly repayment.','/emi-calculator',Calculator],['Deposit calculator','Explore an indicative deposit estimate.','/fd-calculator',Calculator],['Customer support','Get help finding information.','/customer-support',HeartHandshake]];
  const cards=hi?[
    ['वार्षिक रिपोर्ट और लेखापरीक्षित विवरण','बैंक की 42वीं वार्षिक रिपोर्ट में 31 मार्च 2025 को समाप्त वित्त वर्ष की जानकारी है।'],['बैंकिंग सेवाएँ','वित्त वर्ष 2024–25 की रिपोर्ट में SMS बैंकिंग, NEFT / RTGS और QR सुविधा का उल्लेख है।'],['बचत और सावधि जमा','बैंक की रिपोर्ट में बचत, चालू और सावधि जमा श्रेणियाँ शामिल हैं।']
  ]:newsItems.map(([,title,copy])=>[title,copy]);
  return <main lang={language} className="tmb-home">
    <section className="home-hero"><div className="container home-hero-grid"><div className="home-hero-copy"><span className="home-overline"><i/> PROGRESSIVE CO-OPERATIVE BANK</span><motion.h1 initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{duration:.55}}>{hi?<>आपकी योजनाओं के लिए<br/>आपके साथ बढ़ती बैंकिंग</>:<>Your plans deserve<br/>banking that <em>moves with you.</em></>}</motion.h1><p>{hi?'खाते, जमा, ऋण और रोज़मर्रा की बैंकिंग सेवाओं को एक ही जगह से जानें।':'Explore accounts, deposits, loans and everyday banking services from one clear starting point.'}</p><div className="home-hero-actions"><Link className="button button-dark" to="/accounts">{hi?'व्यक्तिगत बैंकिंग देखें':'Explore personal banking'} <ArrowRight size={16}/></Link><Link className="home-text-action" to="/about">{hi?'प्रोग्रेसिव को जानें':'Get to know Progressive'} <ArrowUpRight size={15}/></Link></div><div className="home-assurances"><span><ShieldCheck size={16}/> {hi?'सुरक्षा जानकारी':'Security information'}</span><span><HeartHandshake size={16}/> {hi?'सहकारी मूल्य':'Co-operative values'}</span></div></div><div className="home-hero-art"><div className="banking-hero-visual"><img className="home-banking-illustration" src="/banking-sectors.svg" alt={hi?'बैंकिंग क्षेत्रों का उदाहरण; लाइव खाता डैशबोर्ड नहीं':'Illustrative banking sectors; not a live account dashboard'}/>{[[59.6,21.4,hi?'खुदरा':'Retail'],[80.1,21.4,hi?'जमा':'Deposits'],[48.8,50,'MSME'],[69.3,50,hi?'भुगतान':'Payments'],[89.8,50,hi?'डिजिटल':'Digital'],[59.6,78.6,hi?'ऋण':'Loans'],[80.1,78.6,hi?'सदस्य':'Members']].map(([left,top,label])=><span key={label} className="hex-sector-label" style={{left:left+'%',top:top+'%'}}>{label}</span>)}</div><span className="home-art-caption">{hi?'बैंकिंग क्षेत्रों का उदाहरण · लाइव खाता दृश्य नहीं':'Illustrative banking sectors · not a live account view'}</span></div></div></section>
    <section className="home-freshness" aria-label={hi?'जानकारी और ग्राहक सहायता':'Information and customer support'}><div className="container"><span className="home-freshness-icon"><CircleHelp size={19}/></span><p><b>{hi?'निर्णय लेने से पहले मौजूदा जानकारी जाँचें।':'Check current details before you decide.'}</b><span>{hi?'कुछ जानकारी वित्त वर्ष 2024–25 की वार्षिक रिपोर्ट पर आधारित है। दरें, शुल्क, उत्पादों की उपलब्धता और शर्तें बदल सकती हैं; बैंक से पुष्टि करें।':'Some information is based on the FY 2024–25 annual report. Rates, fees, product availability and terms may change; confirm them with the bank.'}</span></p><Link to="/news">{hi?'स्रोत की तारीखें':'Source dates'} <ArrowRight size={14}/></Link><Link to="/grievance-redressal">{hi?'शिकायत सहायता':'Complaint help'} <ArrowUpRight size={14}/></Link><Link to="/contact">{hi?'बैंक से संपर्क':'Contact bank'} <ArrowUpRight size={14}/></Link></div></section>
    <section className="home-shortcuts"><div className="container"><div className="home-section-heading"><div><span className="home-kicker">{hi?'बैंकिंग एक नज़र में':'BANKING AT A GLANCE'}</span><h2>{hi?'आज हम आपकी कैसे सहायता कर सकते हैं?':'How can we help you today?'}</h2></div><p>{hi?'शुरू करने के लिए कोई सेवा चुनें।':'Choose a service to get started.'}</p></div><div className="home-product-grid">{links.map(([title,copy,path,Icon],i)=><Link className="home-product-card" to={path} key={path}><span className="home-product-icon"><Icon size={21}/></span><span className="home-product-number">0{i+1}</span><b>{title}</b><small>{copy}</small><span className="home-product-link">{hi?'देखें':'Explore'} <ArrowUpRight size={14}/></span></Link>)}</div></div></section>
    <section className="home-feature-band"><div className="container home-feature-inner"><div><span className="home-kicker">{hi?'योजना बनाने का आसान तरीका':'A CLEARER WAY TO PLAN'}</span><h2>{hi?<>अगला कदम<br/><em>आत्मविश्वास से।</em></>:<>Make your next move<br/>with more <em>confidence.</em></>}</h2><p>{hi?'अपने विकल्प समझने के लिए सरल टूल इस्तेमाल करें। कैलकुलेटर अनुमान देते हैं; मौजूदा दरों और शर्तों की पुष्टि बैंक से करें।':'Use simple tools to explore your options. Estimates are indicative; confirm current rates and product terms with the bank.'}</p><Link className="button button-light" to="/emi-calculator">{hi?'ईएमआई का अनुमान लगाएँ':'Estimate a repayment'} <ArrowRight size={15}/></Link></div><div className="home-tool-stack">{[[Calculator,hi?'ईएमआई कैलकुलेटर':'EMI calculator',hi?'मासिक भुगतान का अनुमान':'Estimate a monthly repayment','/emi-calculator'],[PiggyBank,hi?'एफडी कैलकुलेटर':'FD calculator',hi?'जमा राशि का अनुमान':'Indicative deposit estimate','/fd-calculator'],[Landmark,hi?'ब्याज दरें':'Interest rates',hi?'ब्याज दर की जानकारी देखें':'View rate information','/interest-rates'],[Wallet,hi?'ऋण पात्रता कैलकुलेटर':'Loan eligibility calculator',hi?'संभावित ऋण सीमा का अनुमान':'Estimate a possible range','/loan-eligibility-calculator'],[Search,hi?'सेवा श्रेणी खोजें':'Service category finder',hi?'सेवा श्रेणी खोजें':'Search service categories','/service-charge-finder']].map(([Icon,title,copy,path])=><Link to={path} key={path}><span className="home-tool-icon"><Icon size={19}/></span><span><b>{title}</b><small>{copy}</small></span><ArrowUpRight size={16}/></Link>)}</div></div></section>
    <section className="home-updates"><div className="container"><div className="home-section-heading"><div><span className="home-kicker">{hi?'बैंक की जानकारी':'BANK INFORMATION'}</span><h2>{hi?'प्रोग्रेसिव से जानकारी पाएँ।':'Stay informed with Progressive.'}</h2></div><Link className="home-text-action" to="/news">{hi?'सभी जानकारी':'All bank information'} <ArrowRight size={15}/></Link></div><div className="home-news-grid">{cards.map(([title,copy],i)=><Link to={'/news/'+newsItems[i][0]} className="home-news-card" key={newsItems[i][0]}><span className={'home-news-art news-art-'+(i+1)}><img src={['/annual-report.svg','/digital-banking.svg','/deposit-growth.svg'][i]} alt={hi?['वार्षिक रिपोर्ट और वित्तीय विवरण','डिजिटल बैंकिंग और भुगतान सेवाएँ','बचत और सावधि जमा'][i]:['Annual report and financial statements','Digital banking and payment services','Savings and term deposits'][i]} loading="lazy"/><b>0{i+1}</b></span><span className="home-news-meta">{hi?'वार्षिक रिपोर्ट · वित्त वर्ष 2024–25':'Annual report · FY 2024–25'}</span><b className="home-news-title">{title}</b><small>{copy}</small><span className="home-product-link">{hi?'विवरण पढ़ें':'Read details'} <ArrowUpRight size={14}/></span></Link>)}</div></div></section>
    <section className="home-service-ribbon"><div className="container"><div><span className="home-ribbon-icon"><ShieldCheck size={20}/></span><span><b>{hi?'अपनी बैंकिंग जानकारी सुरक्षित रखें':'Protect your banking information'}</b><small>{hi?'सुरक्षा और ग्राहक सहायता की जानकारी पाएँ।':'Find practical security guidance and customer support information.'}</small></span></div><Link to="/customer-awareness">{hi?'सुरक्षा सुझाव':'Safety tips'} <ArrowRight size={15}/></Link><Link to="/customer-support">{hi?'ग्राहक सहायता':'Customer support'} <ArrowUpRight size={15}/></Link></div></section>
    <section className="home-resource-strip"><div className="container"><div className="home-section-heading"><div><span className="home-kicker">{hi?'उपयोगी जानकारी':'HELPFUL INFORMATION'}</span><h2>{hi?'ज़रूरी जानकारी, एक जगह।':'Useful details, in one place.'}</h2></div><Link className="home-text-action" to="/useful-information">{hi?'सभी संसाधन देखें':'Browse all resources'} <ArrowRight size={15}/></Link></div><div className="home-resource-links">{[[hi?'केवाईसी जानकारी':'KYC information','/useful-information/kyc'],[hi?'बैंक अवकाश सूची':'Bank holiday list','/useful-information/bank-holiday-list'],[hi?'लावारिस जमा':'Unclaimed deposits','/useful-information/unclaimed-deposits'],[hi?'सेवा श्रेणियाँ':'Service categories','/service-charges'],[hi?'फ़ॉर्म और डाउनलोड':'Forms and downloads','/downloads']].map(([label,path])=><Link to={path} key={path}><span>{label}</span><ArrowUpRight size={15}/></Link>)}</div></div></section>
    <section className="home-final-cta"><div className="container"><span className="home-kicker">{hi?'हम सहायता के लिए यहाँ हैं':'HERE WHEN YOU NEED US'}</span><h2>{hi?'अगला सही कदम चुनें।':'Find the right next step.'}</h2><p>{hi?'बैंकिंग विकल्प देखें या बैंक से संपर्क करें।':'Browse banking options or contact the bank.'}</p><div><Link className="button button-dark" to="/loans">{hi?'ऋण देखें':'Explore loans'} <ArrowRight size={15}/></Link><Link className="button button-outline" to="/contact">{hi?'संपर्क करें':'Contact us'} <ArrowUpRight size={14}/></Link></div></div></section>
  </main>
}
function App(){const [language,setLanguage]=useState(()=>{try{return localStorage.getItem('pucbl-header-language')==='hi'?'hi':'en'}catch{return 'en'}});useEffect(()=>{try{localStorage.setItem('pucbl-header-language',language)}catch{}},[language]);return <LanguageContext.Provider value={{language,setLanguage}}><BrowserRouter><DisclaimerGate/><Layout/></BrowserRouter></LanguageContext.Provider>}
createRoot(document.getElementById('root')).render(<App/>);





